window.EW=window.EW||{pages:{}};window.EW.pages["wiki-bestiaire--rang-a-2"]={"html":"<div class=\"tbl-wrap\"><table class=\"doc-table\"><thead><tr><th scope=\"col\">Rang<\/th><th scope=\"col\">Description<\/th><\/tr><\/thead><tbody><tr><td>Thérokéras<\/td><td>Grande créature en voie de disparition à l'allure de cerf, douce et majestueuse, qui inspire un respect quasi religieux.<\/td><\/tr><tr><td>Manticore<\/td><td>Lion rougeâtre à tête presque humaine et à queue de scorpion venimeuse, l'une des créatures les plus dangereuses connues.<\/td><\/tr><tr><td>Arachne de l’Abîme<\/td><td>Gigantesque araignée mythique au corps rocailleux, dont la tête hurle sans fin pour désorienter ses victimes.<\/td><\/tr><tr><td><a href=\"#/p/wiki-bestiaire--rang-a-2--griffon\">Griffon<\/a><\/td><td>Créature Mi-Aigle Mi-Lion, fière monture de l'AMRU, d'une puissance insoupçonnée.<\/td><\/tr><tr><td>Ent Corrompu<\/td><td>Créature autrefois sage et bienveillante, corrompue par une force extérieure.<\/td><\/tr><\/tbody><\/table><\/div>","toc":[]};
